import 'package:flutter_local_notifications/flutter_local_notifications.dart';import 'package:flutter_timezone/flutter_timezone.dart';import 'package:timezone/data/latest.dart' as tzdata;import 'package:timezone/timezone.dart' as tz;
class ReminderService{ReminderService._();static final instance=ReminderService._();final _plugin=FlutterLocalNotificationsPlugin();bool _ready=false;
Future<void> initialize()async{if(_ready)return;tzdata.initializeTimeZones();final local=await FlutterTimezone.getLocalTimezone();tz.setLocalLocation(tz.getLocation(local.identifier));await _plugin.initialize(const InitializationSettings(android:AndroidInitializationSettings('@mipmap/ic_launcher')));_ready=true;}
Future<bool> requestPermission()async{await initialize();final p=_plugin.resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>();return await p?.requestNotificationsPermission()??false;}
Future<void> scheduleDaily({required int hour,required int minute})async{await initialize();final now=tz.TZDateTime.now(tz.local);var next=tz.TZDateTime(tz.local,now.year,now.month,now.day,hour,minute);if(!next.isAfter(now))next=tz.TZDateTime(tz.local,now.year,now.month,now.day+1,hour,minute);await _plugin.zonedSchedule(1001,'A moment with AstroDaily','Your daily reading and reflection are ready.',next,const NotificationDetails(android:AndroidNotificationDetails('astrodaily_daily','Daily reading',channelDescription:'Optional daily reading reminder')),androidScheduleMode:AndroidScheduleMode.inexactAllowWhileIdle,matchDateTimeComponents:DateTimeComponents.time);}
Future<void> scheduleWeekly({required int weekday,required int hour,required int minute})async{await initialize();final now=tz.TZDateTime.now(tz.local);var next=tz.TZDateTime(tz.local,now.year,now.month,now.day,hour,minute);while(next.weekday!=weekday||!next.isAfter(now)){next=tz.TZDateTime(tz.local,next.year,next.month,next.day+1,hour,minute);}await _plugin.zonedSchedule(1002,'Your weekly AstroDaily reflection','Take a moment to look back on the week.',next,const NotificationDetails(android:AndroidNotificationDetails('astrodaily_weekly','Weekly reflection',channelDescription:'Optional weekly reflection reminder')),androidScheduleMode:AndroidScheduleMode.inexactAllowWhileIdle,matchDateTimeComponents:DateTimeComponents.dayOfWeekAndTime);}
Future<void> scheduleLunar({required int id,required String phase,required DateTime timestampUtc})async{await initialize();final local=tz.TZDateTime.from(timestampUtc.toLocal(),tz.local);if(local.isAfter(tz.TZDateTime.now(tz.local))){await _plugin.zonedSchedule(id,phase,'A lunar event is coming up.',local,const NotificationDetails(android:AndroidNotificationDetails('astrodaily_lunar','Lunar events',channelDescription:'Optional lunar event reminders')),androidScheduleMode:AndroidScheduleMode.inexactAllowWhileIdle);}}
Future<void> cancelDaily()async{await initialize();await _plugin.cancel(1001);}
Future<void> cancelWeekly()async{await initialize();await _plugin.cancel(1002);}}
